mapper.insert:
INSERT INTO notice (
	notice_id
				, title
				, content
				, important_yn
				, view_count
				, use_yn
				, writer_id
				, created_at
				, updated_by
				, updated_at
 )
VALUES (
	#{noticeId}
				, #{title}
				, #{content}
				, #{importantYn}
				, #{viewCount}
				, #{useYn}
				, #{writerId}
				, #{createdAt}
				, #{updatedBy}
				, #{updatedAt}
 )

mapper.update:
UPDATE notice
SET				title=#{title}				, content=#{content}
	, important_yn=#{importantYn}
	, view_count=#{viewCount}
	, use_yn=#{useYn}
	, writer_id=#{writerId}
	, created_at=#{createdAt}
	, updated_by=#{updatedBy}
	, updated_at=#{updatedAt}
WHERE
	notice_id=#{noticeId}

mapper.select:
SELECT notice_id , title , content , important_yn , view_count , use_yn , writer_id , created_at , updated_by , updated_at FROM notice WHERE 1=1
AND notice_id LIKE #{searchPattern}
AND title LIKE #{searchPattern}
ORDER BY notice_id DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) totcnt
FROM notice
WHERE 1=1




			AND notice_id LIKE #{searchPattern}




			AND title LIKE #{searchPattern}
